 'pow_t_decay': lambda p: p[0]*np.exp(-p[1]*t) + p[2]*A**p[3] + p[4]*A**p[5]*np.exp(-p[6]*t),
 'poly_t_exp': lambda p: p[0]*np.exp(-p[1]*t)+p[2]*A+p[3]*A**2+p[4]*A*np.exp(-p[5]*t)+p[6]*A**2*np.exp(-p[5]*t),
 'rate_sat': lambda p: p[0]*np.exp(-p[1]*t)*(1 - A/p[2]) - p[3]*A**2 + p[4]*t*A,
 'logt': lambda p: p[0] - p[1]*np.log(1+p[2]*t) + p[3]*A + p[4]*A**2 + p[5]*A*np.log(1+p[2]*t),
}
rng=np.random.default_rng(0)
for name,f in models.items():
